#include <list>
#include <algorithm>
#include <iterator>

int main() {
    std::list<int> l = {1, 2, 3, 4, 5};

    // Error: List iterators are not random access
    // auto it_err = l.begin() + 2; 

    // Correct way: use std::advance (O(N) operation)
    auto it = l.begin();
    std::advance(it, 2);

    // l[2] is also invalid
    // std::cout << l[2];

    std::cout << *it << std::endl; // Output: 3
}
